urface: #ffffff;\n  --we-surface-soft: #f4f1e9;\n  --we-text: #26312d;\n  --we-muted: #78827d;\n  --we-border: #e4e4dc;\n  --we-accent: #739b68;\n  --we-accent-strong: #557c4e;\n  --we-accent-contrast: #fff;\n  --we-tint: #edf3e9;\n  --we-input: #fbfaf7;\n  --we-danger: #bc5e65;\n  --we-shadow: 0 4px 16px rgba(31, 42, 35, 0.06);\n  display: grid;\n  grid-template-columns: 232px minmax(0, 1fr);\n  width: min(calc(94vw / var(--we-scale)), calc(1480px / var(--we-scale)));\n  height: min(calc(92vh / var(--we-scale)), calc(940px / var(--we-scale)));\n  overflow: hidden;\n  transform: scale(var(--we-scale));\n  transform-origin: center;\n  border: 1px solid var(--we-border);\n  border-radius: 18px;\n  background: var(--we-bg);\n  color: var(--we-text);\n  box-shadow: 0 26px 80px rgba(7, 12, 18, 0.32);\n  font-family: Inter, 'Segoe UI', 'Microsoft YaHei', sans-serif;\n  font-size: 13px;\n  line-height: 1.5;\n}\n\n.we-workspace[data-theme='light'] {\n  --we-bg: #f5f7f6;\n  --we-surface: #fff;\n  --we-surface-soft: #f2f5f4;\n  --we-text: #243137;\n  --we-muted: #78848a;\n  --we-border: #dfe6e5;\n  --we-accent: #4d8b8b;\n  --we-accent-strong: #306f72;\n  --we-accent-contrast: #fff;\n  --we-tint: #e6f2f0;\n  --we-input: #fbfdfc;\n  --we-danger: #be5360;\n  --we-shadow: 0 4px 16px rgba(31, 52, 55, 0.07);\n}\n\n.we-workspace[data-theme='dark'] {\n  --we-bg: #111925;\n  --we-surface: #1b2635;\n  --we-surface-soft: #202d3d;\n  --we-text: #e8edf0;\n  --we-muted: #9aa9b2;\n  --we-border: #334252;\n  --we-accent: #8aac81;\n  --we-accent-strong: #73986a;\n  --we-accent-contrast: #142018;\n  --we-tint: #2c3c36;\n  --we-input: #141e2b;\n  --we-danger: #ee9095;\n  --we-shadow: 0 4px 18px rgba(0, 0, 0, 0.16);\n}\n\n.we-workspace[data-theme='cream'] {\n  --we-bg: #f4f0e7;\n  --we-surface: #fffdf8;\n  --we-surface-soft: #f2eadc;\n  --we-text: #44392a;\n  --we-muted: #8b7e6b;\n  --we-border: #e7dbc7;\n  --we-accent: #86a96c;\n  --we-accent-strong: #688a53;\n  --we-accent-contrast: #fff;\n  --we-tint: #edf3e7;\n  --we-input: #fbf7ed;\n  --we-danger: #c65f72;\n  --we-shadow: 0 4px 16px rgba(69, 51, 27, 0.06);\n}\n\n.we-workspace[data-theme='landmine'] {\n  --we-bg: #faeff4;\n  --we-surface: #fffafd;\n  --we-surface-soft: #f7e4ed;\n  --we-text: #452b3b;\n  --we-muted: #98758a;\n  --we-border: #efd4e2;\n  --we-accent: #d473a2;\n  --we-accent-strong: #a9507d;\n  --we-accent-contrast: #fff;\n  --we-tint: #f9e2ee;\n  --we-input: #fff7fb;\n  --we-danger: #b54064;\n  --we-shadow: 0 4px 16px rgba(89, 38, 69, 0.08);\n}\n\n.we-sidebar {\n  display: flex;\n  min-width: 0;\n  flex-direction: column;\n  padding: 20px 14px 14px;\n  border-right: 1px solid var(--we-border);\n  background: var(--we-surface);\n}\n\n.we-brand {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 0 5px 20px;\n}\n\n.we-brand-mark {\n  display: grid;\n  width: 39px;\n  height: 39px;\n  place-items: center;\n  border-radius: 12px;\n  background: linear-gradient(145deg, var(--we-accent), var(--we-accent-strong));\n  color: var(--we-accent-contrast);\n  font-family: Georgia, serif;\n  font-size: 22px;\n  font-weight: 800;\n  box-shadow: var(--we-shadow);\n}\n\n.we-brand-copy {\n  display: grid;\n  line-height: 1.25;\n}\n\n.we-brand-copy strong {\n  font-size: 15px;\n  letter-spacing: 0.04em;\n}\n\n.we-brand-copy span {\n  margin-top: 4px;\n  color: var(--we-muted);\n  font-size: 9px;\n  letter-spacing: 0.11em;\n}\n\n.we-chat-chip {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  min-width: 0;\n  margin-bottom: 18px;\n  padding: 8px 9px;\n  border: 1px solid var(--we-border);\n  border-radius: 9px;\n  background: var(--we-bg);\n  color: var(--we-muted);\n  font-size: 11px;\n}\n\n.we-chat-chip > span:last-child {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.we-live-dot,\n.we-status-dot,\n.we-run-mark {\n  width: 8px;\n  height: 8px;\n  flex: none;\n  border-radius: 50%;\n  background: var(--we-accent);\n}\n\n.we-live-dot {\n  box-shadow