ustify-content: space-between;\n  gap: 14px;\n  min-height: 74px;\n  padding: 12px 23px;\n  border-bottom: 1px solid var(--we-border);\n  background: var(--we-surface);\n}\n\n.we-breadcrumb {\n  color: var(--we-muted);\n  font-size: 10px;\n}\n\n.we-breadcrumb span {\n  padding: 0 5px;\n  color: var(--we-border);\n}\n\n.we-topbar-title h1 {\n  margin: 2px 0 0;\n  font-size: 18px;\n  font-weight: 750;\n  letter-spacing: 0.02em;\n}\n\n.we-topbar-actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.we-revision-chip {\n  padding: 5px 9px;\n  border: 1px solid var(--we-border);\n  border-radius: 999px;\n  background: var(--we-bg);\n  color: var(--we-muted);\n  font-size: 10px;\n}\n\n.we-revision-chip strong {\n  padding-left: 3px;\n  color: var(--we-text);\n}\n\n.we-close {\n  display: grid;\n  width: 31px;\n  height: 31px;\n  place-items: center;\n  border: 1px solid var(--we-border);\n  border-radius: 9px;\n  background: var(--we-surface);\n  color: var(--we-muted);\n  cursor: pointer;\n  font: inherit;\n  font-size: 23px;\n  line-height: 1;\n}\n\n.we-close:hover {\n  border-color: var(--we-danger);\n  color: var(--we-danger);\n}\n\n.we-page-scroll {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  overflow: auto;\n  padding: 21px 24px 26px;\n  background: var(--we-bg);\n  scrollbar-color: var(--we-border) transparent;\n}\n\n.we-page {\n  width: 100%;\n  max-width: 1280px;\n  min-height: 100%;\n  margin: 0 auto;\n}\n\n.we-welcome {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 20px;\n  padding: 22px 24px;\n  border: 1px solid color-mix(in srgb, var(--we-accent) 24%, var(--we-border));\n  border-radius: 16px;\n  background:\n    radial-gradient(ellipse at 90% 5%, color-mix(in srgb, var(--we-accent) 13%, transparent), transparent 52%),\n    var(--we-surface);\n  box-shadow: var(--we-shadow);\n}\n\n.we-eyebrow {\n  margin: 0 0 7px;\n  color: var(--we-accent-strong);\n  font-size: 10px;\n  font-weight: 800;\n  le